            Rect(0,0,1600,900,ink);Text(65,35,1300,60,"Controls",title,48);Text(68,109,1400,42,bindingCapture==""?"Choose an action, then press a key or mouse button. Escape cancels rebinding and always opens the menu.":"Press a new key for "+bindingCapture+". Escape cancels.",body,20);
            var ev=Event.current;if(bindingCapture!=""&&(ev.type==EventType.KeyDown||ev.type==EventType.MouseDown)){var key=ev.type==EventType.MouseDown?(KeyCode)((int)KeyCode.Mouse0+ev.button):ev.keyCode;if(key!=KeyCode.Escape)GameBindings.Bind(bindingCapture,key);bindingCapture="";ev.Use();}
